package top.monitorglobal.tv;
import android.content.*;import android.graphics.PixelFormat;import android.os.*;import android.provider.Settings;import android.view.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;
/** One delayed, static satellite card following an hourly weather presentation. */
final class WeatherSatelliteSequence implements AutoCloseable {
 static final long AFTER_WEATHER=13000,DURATION=15000,TOTAL=AFTER_WEATHER+5000+DURATION+500;
 interface Loader {WeatherSatelliteClient.Frame load()throws Exception;void close();}
 private final Context context;private final BooleanSupplier allowed;private final Handler main=new Handler(Looper.getMainLooper());private final java.util.function.Supplier<Loader> factory;private ExecutorService worker;private Loader reader;private WeatherSatelliteClient.Frame frame;private WeatherSatelliteCard card;private View current;private int generation;private boolean closed,pending;
 WeatherSatelliteSequence(Context c,BooleanSupplier allowed){this(c,allowed,()->{WeatherSatelliteClient client=new WeatherSatelliteClient(c);return new Loader(){public WeatherSatelliteClient.Frame load()throws Exception{return client.latest(InfraredPlan.SOUTHEAST,System.currentTimeMillis());}public void close(){client.close();}};});}
 WeatherSatelliteSequence(Context c,BooleanSupplier allowed,java.util.function.Supplier<Loader> factory){context=c;this.allowed=allowed;this.factory=factory;}
 void start(){cancel();if(closed)return;pending=true;int token=++generation;long showAt=SystemClock.uptimeMillis()+AFTER_WEATHER;reader=factory.get();Loader operation=reader;if(worker==null)worker=Executors.newSingleThreadExecutor();
  main.postDelayed(()->{if(token==generation&&pending&&current==null){Prefs.get(context).edit().putString("satelliteStatus","Satélite: fonte indisponível nesta apresentação").apply();cancel();}},AFTER_WEATHER+5000);
  worker.execute(()->{WeatherSatelliteClient.Frame result=null;try{result=operation.load();}catch(Exception|OutOfMemoryError ignored){}WeatherSatelliteClient.Frame ready=result;main.post(()->{if(closed||token!=generation){if(ready!=null)ready.close();return;}if(ready==null){Prefs.get(context).edit().putString("satelliteStatus","Satélite: sem imagem recente disponível").apply();cancel();return;}frame=ready;Prefs.get(context).edit().putString("satelliteStatus",InfraredPlan.timing(ready.at,System.currentTimeMillis())).apply();main.postDelayed(()->show(token),Math.max(0,showAt-SystemClock.uptimeMillis()));});});
 }
 private void show(int token){if(closed||token!=generation||frame==null)return;PowerManager power=context.getSystemService(PowerManager.class);if(!allowed.getAsBoolean()||power!=null&&!power.isInteractive()||!Settings.canDrawOverlays(context)){cancel();return;}try{card=new WeatherSatelliteCard(context,frame,false);int densityWidth=Math.round(420*context.getResources().getDisplayMetrics().density);WindowManager.LayoutParams p=new WindowManager.LayoutParams(Math.min(densityWidth,context.getResources().getDisplayMetrics().widthPixels*46/100),WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.RIGHT;p.x=p.y=Math.round(28*context.getResources().getDisplayMetrics().density);context.getSystemService(WindowManager.class).addView(card,p);current=card;main.postDelayed(()->{if(token==generation)cancel();},DURATION);}catch(RuntimeException error){cancel();}}
 boolean pending(){return pending;}
 void cancel(){generation++;pending=false;main.removeCallbacksAndMessages(null);if(current!=null){try{context.getSystemService(WindowManager.class).removeView(current);}catch(RuntimeException ignored){}current=null;}if(card!=null){card.clear();card=null;}if(frame!=null){frame.close();frame=null;}if(reader!=null){reader.close();reader=null;}}
 public void close(){closed=true;cancel();if(worker!=null)worker.shutdownNow();}
}
